// A new network's subnet is generated by the daemon, never typed.
//
// Letting a user choose the address is how two networks end up on the same
// /24, or a network collides with the host's own LAN or a VPN. So the create
// form's field is read-only and carries a generated value, with a re-roll
// button as the only way to change it -- and the re-roll goes back to the
// daemon, which checks every subnet already in use.
//
// The edit path is deliberately left alone: an existing network's subnet is
// shown editable, with no re-roll, or an administrator could not correct one.
//
// Driven by running the real app in jsdom with `fetch` stubbed, the same way
// profile-limits.test.mjs does, so this runs anywhere with no backend.
//
// Run: pnpm test

import assert from "node:assert/strict";
import test, { before } from "node:test";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

let appCode;

before(() => {
  // The app is only reachable as a bundle; build the IIFE the live suites use.
  execFileSync("npx", ["vite", "build", "--logLevel", "error", "--outDir", "test/_live",
    "--assetsDir", ".", "--target", "es2020"],
    { cwd: process.cwd(), stdio: "ignore", env: { ...process.env, VM_IIFE: "1" } });
  appCode = readFileSync("test/_live/app.iife.js", "utf8");
});

/// Boot the app with one online server that has one network called "lan", then
/// open the create form and return the subnet field and its re-roll button.
///
/// `subnets` is what the stubbed `/networks/suggest-subnet` hands out, in
/// order, so a re-roll can be told apart from the first suggestion.
async function openCreateForm(subnets = ["10.42.7.0/24", "10.99.12.0/24"]) {
  const { JSDOM, VirtualConsole } = await import("jsdom");
  const dom = new JSDOM(
    '<!doctype html><html data-theme="dark"><body><div id="app"></div></body></html>',
    { url: "http://127.0.0.1:8799/", runScripts: "dangerously", pretendToBeVisual: true,
      virtualConsole: new VirtualConsole() },
  );
  const { window } = dom;
  let handed = 0;
  const json = (body) => Promise.resolve({
    ok: true, status: 200, headers: { get: () => null },
    json: () => Promise.resolve(body),
    text: () => Promise.resolve(JSON.stringify(body)),
  });
  const CONN = { id: "c1", name: "hv", url: "https://h:8443", online: true };
  const NET = { name: "lan", uuid: "u-1", title: "lan", subnet: "10.9.0.1/24",
    ip: "10.9.0.1/24", forward: "nat", active: true, bridge: "virbr1" };
  window.fetch = (input) => {
    const url = typeof input === "string" ? input : input.url;
    const path = url.replace(/^https?:\/\/[^/]+/, "");
    if (url.includes("/auth/status")) return json({ needs_setup: false, auth_disabled: false });
    if (url.includes("/auth/me")) return json({ id: "a1", username: "root", nickname: "Root",
      avatar: null, admin: true, privs: [] });
    if (path === "/connections") return json([CONN]);
    // The one that matters: the daemon's suggestion, handed out in order.
    if (url.includes("/networks/suggest-subnet")) {
      const subnet = subnets[Math.min(handed, subnets.length - 1)];
      handed++;
      return json({ subnet, used: 3 });
    }
    if (url.includes("/networks/bridges")) return json(["br0"]);
    if (url.includes("/networks")) return json([NET]);
    return json([]);
  };
  window.eval(appCode);
  const wait = (ms) => new Promise((r) => window.setTimeout(r, ms));
  const click = (el) => el?.dispatchEvent(new window.MouseEvent("click", { bubbles: true }));
  await wait(600);
  // Select the server in the tree, then its Networks tab: the create button
  // lives on the server's own page, not the Datacenter's (which uses a
  // daemon picker when nothing is selected).
  click(window.document.querySelector("#tree [data-conn]"));
  await wait(600);
  click([...window.document.querySelectorAll(".tabbar .tab")]
    .find((t) => t.textContent.trim() === "Networks"));
  await wait(600);
  const btn = window.document.querySelector("#create-net");
  assert.ok(btn, `a Create Network button is reachable (path ${window.location.pathname})`);
  click(btn);
  // Long enough for the form to render and the suggestion it fires on open to
  // land; the value is asserted below, so a short wait fails loudly.
  await wait(900);
  return {
    window,
    ip: window.document.querySelector("#net-ip"),
    reroll: window.document.querySelector("#net-ip-reroll"),
    click: () => click(window.document.querySelector("#net-ip-reroll")),
    wait,
    handed: () => handed,
  };
}

test("a new network's subnet is generated and cannot be typed", async () => {
  const f = await openCreateForm();
  try {
    assert.ok(f.ip, "the subnet field is in the create form");
    assert.equal(
      f.ip.hasAttribute("readonly"), true,
      "the field must be read-only, or a user can pick an address that collides",
    );
    assert.equal(f.ip.value, "10.42.7.0/24", `prefilled from the daemon: ${f.ip.value}`);
    // The label no longer says "optional": the value is not the user's to give.
    const label = f.ip.closest("label")?.querySelector("span")?.textContent ?? "";
    assert.ok(!/optional/i.test(label), `the label must not say optional: ${label}`);
  } finally {
    f.window.close();
  }
});

test("the only way to change it is to re-roll, which asks the daemon again", async () => {
  const f = await openCreateForm(["10.42.7.0/24", "10.99.12.0/24"]);
  try {
    assert.ok(f.reroll, "a re-roll button is present");
    assert.equal(f.handed(), 1, "the first suggestion was fetched once");
    f.click();
    await f.wait(400);
    assert.equal(f.ip.value, "10.99.12.0/24", `re-roll asks again: ${f.ip.value}`);
    assert.equal(f.handed(), 2, "the re-roll went back to the daemon, which re-checks conflicts");
    // Still read-only after a re-roll, or the second click would be free typing.
    assert.equal(f.ip.hasAttribute("readonly"), true, "still read-only after re-rolling");
  } finally {
    f.window.close();
  }
});

test("changing the mode re-rolls, and bridge mode needs no subnet", async () => {
  const f = await openCreateForm(["10.42.7.0/24", "10.99.12.0/24"]);
  try {
    const sel = f.window.document.querySelector("#net-mode");
    assert.ok(sel, "the mode picker is in the form");
    // Isolated still carries a subnet, so a change re-asks for one.
    sel.value = "none";
    sel.dispatchEvent(new f.window.Event("change", { bubbles: true }));
    await f.wait(400);
    assert.equal(f.handed(), 2, "switching mode re-rolls");
    // Bridge mode takes its addressing from the bridge: no request, and the
    // field is hidden rather than left showing a stale address.
    sel.value = "bridge";
    sel.dispatchEvent(new f.window.Event("change", { bubbles: true }));
    await f.wait(400);
    assert.equal(f.handed(), 2, "bridge mode asks for nothing");
    const field = f.ip.closest("[data-net-field]");
    assert.equal(field?.hidden, true, "the subnet field is hidden in bridge mode");
  } finally {
    f.window.close();
  }
});

/// The DHCP range is no longer a form field: this daemon's own DHCP hands out
/// the whole subnet (every address permanent), so a range here would only be a
/// second, conflicting answer.
test("the DHCP range is not a form field", async () => {
  const f = await openCreateForm();
  try {
    for (const id of ["#net-dhcp-start", "#net-dhcp-end"]) {
      assert.equal(
        f.window.document.querySelector(id), null,
        `${id} must be gone from the network form`,
      );
    }
  } finally {
    f.window.close();
  }
});

/// An isolated network is usually a private segment the operator routes
/// themselves -- a dummy interface or a private routed network -- so carrying
/// no subnet at all has to be expressible. The trash clears it and re-roll puts
/// one back; NAT has no trash, since it cannot run without a subnet.
test("the trash clears the subnet for an isolated network, and re-roll restores it", async () => {
  const f = await openCreateForm(["10.42.7.0/24", "10.99.12.0/24"]);
  try {
    const sel = f.window.document.querySelector("#net-mode");
    const clear = () => f.window.document.querySelector("#net-ip-clear");
    const setMode = async (m) => {
      sel.value = m;
      sel.dispatchEvent(new f.window.Event("change", { bubbles: true }));
      await f.wait(350);
    };
    assert.ok(clear(), "the create form offers a trash beside re-roll");

    // NAT needs a subnet, so there is nothing to clear: no trash, re-roll shown.
    await setMode("nat");
    assert.equal(clear().hidden, true, "NAT must not offer to clear the subnet");
    assert.equal(f.reroll.hidden, false, "...but does offer re-roll");

    // Isolated: with a subnet the trash is offered.
    await setMode("none");
    assert.ok(f.ip.value, `isolated still gets a subnet by default: ${f.ip.value}`);
    assert.equal(clear().hidden, false, "isolated with a subnet offers the trash");

    // Clearing empties the field, and the trash goes away because there is
    // nothing left to clear; re-roll appears as the way back.
    clear().dispatchEvent(new f.window.MouseEvent("click", { bubbles: true }));
    await f.wait(300);
    assert.equal(f.ip.value, "", `clearing empties the subnet: ${f.ip.value}`);
    assert.equal(clear().hidden, true, "nothing left to clear, so no trash");
    assert.equal(f.reroll.hidden, false, "re-roll is the way back");

    // Re-rolling brings a subnet back, and with it the trash.
    const before = f.handed();
    f.reroll.dispatchEvent(new f.window.MouseEvent("click", { bubbles: true }));
    await f.wait(400);
    assert.ok(f.ip.value, `re-roll restores a subnet: ${f.ip.value}`);
    assert.equal(f.handed(), before + 1, "and asked the daemon for it");
    assert.equal(clear().hidden, false, "the trash is back with the subnet");

    // Switching to NAT after clearing must not leave a subnet-less NAT network
    // behind: the field is refilled by the mode change.
    clear().dispatchEvent(new f.window.MouseEvent("click", { bubbles: true }));
    await f.wait(250);
    assert.equal(f.ip.value, "");
    await setMode("nat");
    assert.ok(f.ip.value, `a mode change refills it: ${f.ip.value}`);
  } finally {
    f.window.close();
  }
});
